        if (k < ck && (v != cv || true)) {
            int p = pos[1].get(k);
            int moveCost = Math.max(freq[p][0] - v, 0) + Math.max(freq[p][1] - k, 0) + Math.max(freq[p][2] - s, 0) - 1;
            int[] newCount = Arrays.copyOf(countUsed, 3);
            newCount[1]++;
            res = Math.min(res, compute(newCount, maxCount, pos, freq, dp) + moveCost);
        }
        if (s < cs) {
