#include <bits/stdc++.h>
using namespace std;

int compute(vector<int>& countUsed, vector<int>& maxCount, vector<vector<int>>& pos, vector<vector<int>>& freq, vector<vector<vector<vector<int>>>>& dp) {
    int v = countUsed[0], k = countUsed[1], s = countUsed[2];
    int cv = maxCount[0], ck = maxCount[1], cs = maxCount[2];
    if (v == cv && k == ck && s == cs) return 0;
    if (dp[v][k][s][0] != -1) return dp[v][k][s][0]; // arbitrary index check
    int res = INT_MAX / 2;

    if (v < cv) {
        int p = pos[0][v];
        int moveCost = max(freq[p][0] - v, 0) + max(freq[p][1] - k, 0) + max(freq[p][2] - s, 0) - 1;
        vector<int> newCount = countUsed;
        newCount[0]++;
        res = min(res, compute(newCount, maxCount, pos, freq, dp) + moveCost);
    }
    if (k < ck && (v != cv || true)) {
        int p = pos[1][k];
        int moveCost = max(freq[p][0] - v, 0) + max(freq[p][1] - k, 0) + max(freq[p][2] - s, 0) - 1;
        vector<int> newCount = countUsed;
        newCount[1]++;
        res = min(res, compute(newCount, maxCount, pos, freq, dp) + moveCost);
    }
    if (s < cs) {
        int p = pos[2][s];
        int moveCost = max(freq[p][0] - v, 0) + max(freq[p][1] - k, 0) + max(freq[p][2] - s, 0) - 1;
        vector<int> newCount = countUsed;
        newCount[2]++;
        res = min(res, compute(newCount, maxCount, pos, freq, dp) + moveCost);
    }
    return dp[v][k][s][0] = res; // assign at index 0
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;
    vector<char> c(s.begin(), s.end());

    int countV = 0, countK = 0, countOthers = 0;
    vector<vector<int>> frequency(n + 1, vector<int>(3, 0));
    vector<vector<int>> positions(3);
    for (int i = 0; i < 3; i++) positions[i] = vector<int>();
    int index = 0;
    for (char ch : c) {
        if (ch == 'V') {
            frequency[index + 1] = frequency[index];
            frequency[index + 1][0]++;
            countV++;
            positions[0].push_back(index + 1);
        } else if (ch == 'K') {
            frequency[index + 1] = frequency[index];
            frequency[index + 1][1]++;
            countK++;
            positions[1].push_back(index + 1);
        } else {
            frequency[index + 1] = frequency[index];
            frequency[index + 1][2]++;
            countOthers++;
            positions[2].push_back(index + 1);
        }
        index++;
    }

    vector<vector<vector<vector<int>>>> memo(
        countV + 1,
        vector<vector<vector<int>>>(
            countK + 1,
            vector<vector<int>>(
                countOthers + 1,
                vector<int>(3, -1)
            )
        )
    );

    vector<int> startCount = {0, 0, 0};
    vector<int> maxCount = {countV, countK, countOthers};
    cout << compute(startCount, maxCount, positions, frequency, memo) << "\n";

    return 0;
}

